--   ('c0000000-0000-4000-8000-000000000003', 'a0000000-0000-4000-8000-000000000001', 'Client check-in', 'servicing', 'check-in', 'A fortnightly call with each client: questions, results, next steps.')
-- on conflict do nothing;
